#!/usr/bin/env python3
"""Rapport V3 : source unique96 et alias mesurés, sans donnée de maison."""
import html,json,pathlib,re
HERE=pathlib.Path(__file__).resolve().parent;ROOT=HERE.parents[1]
OUT=ROOT/'docs/proposition/analyse';D=json.loads((HERE/'sorties/resultats.json').read_text());V2=json.loads((HERE.parent/'catalogue-banc/sorties/resultats.json').read_text());M=json.loads((HERE.parent/'catalogue-banc/charges/manifest.json').read_text())
LABELS={'mirror':'Miroir copié','row_alias':'Alias en ligne96 o','id_lookup':'ID recherché','handle':'Emplacement + génération','pointer':'Adresse mémoire fixe'}
def get(dataset,scale,fanout,variant):return next(r for r in D['results'] if (r['dataset'],r['scale'],r['fanout'],r['variant'])==(dataset,scale,fanout,variant))
def esc(v):return html.escape(str(v))
def num(v):return f'{int(v):,}'.replace(',',' ')
def mem(v):return f'{num(v)} o · {v/1048576:.3f} Mio'
def table(h,rs):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in r)+'</tr>' for r in rs)+'</tbody></table></div>'
sections=[]
def sec(id,title,text):sections.append((id,title,'<section id="'+id+'"><div class="eyebrow">Source unique / V3</div><h2>'+title+'</h2>'+text+'</section>'))
b=get('somme-detail',1,1,'handle');m=get('somme-detail',1,1,'mirror');h4=get('somme-detail',1,4,'handle');m4=get('somme-detail',1,4,'mirror');r96=get('somme-detail',1,1,'row_alias');r964=get('somme-detail',1,4,'row_alias')
sec('decision','Une seule valeur de référence, plusieurs façons de la voir.',f'''<p class="lead">Ton intuition est confirmée sur le prototype : un alias virtuel pur n’a pas besoin de recopier la valeur, ses dates ou ses bornes. La V3 conserve une ligne canonique de <b>96 octets</b> par valeur physique ou calculée, et remplace les lignes d’alias complètes par des liens compacts.</p><div class="recommend"><b>Choix proposé : lignes canoniques 96 o + alias de 32 o avec emplacement et génération.</b><p>L’alias reçoit sa propre identité sans recevoir sa propre copie d’état. Le lien cache le résultat de la résolution d’ID : il n’effectue pas une recherche HashMap à chaque lecture. Les pointeurs bruts restent une optimisation à réserver à un propriétaire de mémoire immobilisée et strictement contrôlé. Un calcul conserve son propre état et sa propre ligne de 96 o.</p></div><p>Sur les deux exports développés et un alias pour chacun des {num(b['source_rows'])} états principaux : {mem(b['allocations_requested_bytes'])} pour le partage, contre {mem(r96['allocations_requested_bytes'])} avec un alias occupant encore96 o, sans copie d’état. À quatre alias par état : économie de {mem(r964['allocations_requested_bytes']-h4['allocations_requested_bytes'])} face aux alias96 o ; {mem(m4['allocations_requested_bytes']-h4['allocations_requested_bytes'])} face aux miroirs synchronisés. Les créations d’objets virtuels sont des scénarios synthétiques, pas l’inventaire de virtuels réellement configurés dans les maisons.</p>''')
sec('liaison','Ce que contient le lien, et ce qu’il ne duplique pas', '''<div class="flow"><span><b>Équipement virtuel #100</b><br>sa propre identité · fiche 96 o</span><i>→</i><span><b>Alias #101</b><br>propriétaire #100 · source #501<br>emplacement + génération · 32 o</span><i>→</i><span><b>Valeur physique #501</b><br>valeur, dates, bornes · 96 o<br>propriétaire physique conservé</span></div><pre>Alias32 — format proposé et mesuré en Rust
  alias_id          u64    8 o   identité propre de la propriété virtuelle
  virtual_owner_id  u64    8 o   équipement virtuel qui la présente
  source_id         u64    8 o   identité durable de la valeur canonique
  cached_slot       u32    4 o   emplacement résolu, recalculable au chargement
  generation        u32    4 o   rejette un emplacement devenu périmé
                            32 o

Valeur canonique Row96
  ID + parent physique, charge scalaire/handle, trois dates,
  schéma et capacités, min/max/pas/origine : une seule copie.

Valeur calculée Row96
  propre ID, résultat, dates et version ; dépendances stockées à côté.</pre><p>Le numéro d’emplacement n’est pas l’identité. Le lien garde source_id pour être reconstitué après chargement ; les IDs restent uniques dans leur catalogue. Entre installations, l’identité complète associe l’installation et l’ID local. Le propriétaire virtuel n’écrase jamais le parent physique.</p><p>Un handle nu prend 8 o dans ce modèle, mais il ne contient pas à lui seul les trois identités ci-dessus. Dire « l’alias ne coûte que 8 o » déplacerait ce coût dans un autre index. La liaison complète mesurée coûte 32 o ; libellés spécifiques au virtuel, restrictions locales ou adaptations supplémentaires sont à ajouter s’ils ne sont pas partagés.</p><p>Si l’on souhaite conserver des <b>blocs de 96 o</b> pour l’allocation, un bloc peut contenir trois Alias32. Cela ne crée pas trois nouvelles copies de valeur. Cette mise en pages n’a pas été chronométrée séparément et ne promet pas un alignement sur une ligne de cache matérielle.</p>''')
sec('rust','Rust partage la donnée ; il ne maintient pas automatiquement une copie.', '''<p>Une référence Rust <code>&amp;Row96</code> permet de lire la ligne existante pendant la durée de son emprunt. Elle ne crée pas un nouvel état. Le catalogue peut fournir cette référence après une résolution contrôlée du lien :</p><pre>Vue persistée : source_id
Vue chargée   : source_id + emplacement + génération
Lecture       : catalogue.resolve(lien) → Option&lt;&amp;Row96&gt;
Mise à jour   : le propriétaire modifie une seule Row96
Lecture alias : consulte cette même Row96, sans synchronisation de copie</pre><p>Le cache du lien est interne à une instance/version du catalogue. Aucun emprunt ni pointeur ne doit survivre à sa destruction, à une reconstruction incompatible ou à une attente asynchrone qui libère sa protection. Une époque de catalogue et une publication cohérente des nouveaux liens sont nécessaires lors d’un rechargement.</p>'''+table(['Mécanisme','Intérêt','Contraintes'],[['Référence &Row96','Lecture sûre et directe, vérifiée par les emprunts Rust','Sa durée de vie est liée au catalogue ; elle n’est pas une adresse durable sérialisable.'],['Emplacement + génération','Accès indexé, pas de HashMap sur chaque lecture ; déplacement du Vec accepté','Validation génération + identité, invalidation et reconstruction des caches nécessaires.'],['NonNull<Row96> / pointeur brut','Lecture directe mesurable sur allocation fixe','La mémoire doit rester vivante et à la même adresse ; déréférencement unsafe et règles d’aliasing à respecter.'],['Arc<RwLock<Row96>>','Partage possédé avec accès concurrent contrôlé','Allocations, compteurs atomiques et verrou par valeur ; non comparé de bout en bout dans ce banc.'],['Arc du catalogue + emprunts courts','Propriété partagée au niveau du catalogue, sans un Arc par état','Il faut toujours définir qui écrit et comment les versions/lecteurs sont synchronisés.']])+'''<p>Un <code>Vec</code> peut déplacer son buffer en grandissant : une adresse dans ce buffer n’est donc pas un lien permanent. Un <code>Box&lt;[Row96]&gt;</code> immobilise l’allocation tant qu’elle est conservée ; <code>Pin</code> ne remplace ni sa propriété, ni sa durée de vie, ni la synchronisation. Un <code>Arc</code> rend la propriété partageable, pas la mutation libre ni automatiquement thread-safe.</p><p>Sources primaires : <a href="https://doc.rust-lang.org/std/vec/struct.Vec.html">Vec et validité des pointeurs</a>, <a href="https://doc.rust-lang.org/std/boxed/">Box</a>, <a href="https://doc.rust-lang.org/std/pin/struct.Pin.html">Pin</a>, <a href="https://doc.rust-lang.org/std/sync/struct.Arc.html">Arc</a>, <a href="https://doc.rust-lang.org/std/sync/struct.RwLock.html">RwLock</a>, <a href="https://doc.rust-lang.org/core/ptr/struct.NonNull.html">NonNull et obligations de sûreté</a>.</p>''')
sec('comparaison','Cinq représentations testées avec les mêmes identités et observations',table(['Variante','Par alias','Accès','Mise à jour source'],[['Miroir copié','32 o de liaison +96 o de copie =128 o','Lecture de la copie locale','Écrit la source puis recopie96 o vers chaque alias concerné.'],['Alias en ligne96 o','32 o de lien +64 o réservés =96 o','Même cache emplacement/génération que le lien compact','Écrit la source une seule fois ; aucune copie de l’état physique.'],['ID recherché','32 o','Recherche source_id dans l’index à chaque lecture','Écrit la source une seule fois.'],['Emplacement + génération','32 o','Index de tableau en cache, génération et ID contrôlés','Écrit la source une seule fois.'],['Adresse mémoire fixe','32 o','NonNull dans une allocation conservée ; identité/vie contrôlées','Écrit la source une seule fois, propriétaire exclusif.']])+'''<p>Les cinq variantes allouent le même index global des IDs canoniques, équipements virtuels et alias, le même index inverse source→alias et un tableau de générations. Chacune réserve une ligne96 par équipement virtuel, à raison d’un équipement pour quatre alias dans ces scénarios. Les 918 contrats d’action et les autres lignes déjà présents dans les exports restent dans le catalogue de référence. Des liaisons d’actions supplémentaires par équipement ne sont pas ajoutées ici : leur coût doit être budgété séparément, comme le scénario liens4 de la V2.</p><p>La variante pointeur utilise une allocation gelée possédée par le banc. Les emprunts retournés sont liés au banc ; les écritures exigent un accès exclusif. Elle n’implémente ni redimensionnement, ni concurrence, ni reconstruction de catalogue. Des tests fonctionnels ne constituent pas une preuve formelle d’absence d’UB ; Miri et une intégration de production ne font pas partie des validations réalisées.</p>''')
memrows=[]
for dataset,scale,fanout in [('a-principal',1,1),('b-principal',1,1),('somme-principal',1,1),('somme-detail',1,1),('somme-detail',1,4),('somme-detail',1,16),('somme-detail',10,1),('somme-detail',10,4),('somme-detail',100,1)]:
 mirror=get(dataset,scale,fanout,'mirror');fullalias=get(dataset,scale,fanout,'row_alias');shared=get(dataset,scale,fanout,'handle')
 memrows.append([dataset+' ×'+str(scale),fanout,num(shared['aliases']),num(shared['virtual_equipment_rows']),mem(mirror['allocations_requested_bytes']),mem(fullalias['allocations_requested_bytes']),mem(shared['allocations_requested_bytes']),mem(fullalias['allocations_requested_bytes']-shared['allocations_requested_bytes'])])
sec('memoire','Le coût mémoire mesuré, avec index et notifications',table(['Charge','Alias/source','Alias','Équipements virtuels','Miroirs copiés','Alias96 o','Liens32 o','Gain sur alias96 o'],memrows)+'''<p>Les trois variantes à lien32 o ont le même nombre d’octets demandés dans ce périmètre. Le gain exact est <code>64 × nombre_d_alias</code> face à la ligne d’alias96 o, et <code>96 × nombre_d_alias</code> face au miroir128 o, à identités et index égaux. Mon exemple précédent utilisait déjà une référence à la source : son gaspillage était l’enveloppe complète, pas une seconde valeur. Les deux cas sont maintenant distingués.</p>'''+table(['Composant · somme développée ×1, quatre alias/source','Miroirs','Partage'],[[label,mem(get('somme-detail',1,4,'mirror')[key]),mem(get('somme-detail',1,4,'handle')[key])] for label,key in [('Catalogue de référence96','canonical_bytes'),('Équipements virtuels96','virtual_equipment_bytes'),('Liaisons ou miroirs','bindings_bytes'),('Générations','generations_bytes'),('Index de notifications','reverse_index_bytes'),('Index global des IDs','identity_index_bytes'),('Liste des sources','source_slots_bytes'),('Pool de données annexes','payload_pool_bytes')]])+'''<p>Le pool est réellement alloué et touché ; ses octets fictifs ont les longueurs des données expurgées déjà inventoriées. Les schémas sont des références stub et leur contenu n’est pas interprété. Les libellés et permissions propres à de nouveaux virtuels ne sont pas inventoriés. Les octets mesurés sont les allocations vivantes du prototype, pas le RSS ni la mémoire de Moli complet.</p>''')
perf=[]
for scale,fanout in [(1,1),(1,4),(1,16),(10,1),(10,4),(100,1)]:
 for variant in LABELS:
  r=get('somme-detail',scale,fanout,variant)
  perf.append([f'×{scale} / {fanout}',LABELS[variant],f"{r['scalar_ns_per_op']:.2f}",f"{r['numeric_ns_per_op']:.2f}",f"{r['source_update_notify_ns_per_op']:.2f}"])
sec('vitesse','Lire et propager : le pointeur est rapide, la recherche répétée d’ID coûte davantage.',table(['Échelle / alias par source','Variante','Scalaire + dates ns/lecture','Nombre + bornes ns/lecture','Modification + notifications ns/source'],perf)+'''<p>Chaque ligne est la médiane de trois processus neufs ; chacun mesure sept passages après échauffement. Les lectures aléatoires utilisent environ un million d’accès par passage, hors préparation des index d’essai. Le nombre d’écritures par passage dépend du facteur d’alias et figure dans les sorties brutes. Les cinq variantes reçoivent la même séquence d’écritures pour une charge donnée.</p><p>Les pointeurs obtiennent les meilleures lectures dans ces essais. Leur coût mémoire est pourtant identique à celui du handle complet. Le handle évite l’essentiel du coût de recherche d’ID tout en acceptant le déplacement du tableau, au prix de ses contrôles. Les accès ne portent pas exactement les mêmes garanties : le handle vérifie génération et bornes ; le pointeur bénéficie d’une allocation gelée sans réemploi. Ce n’est donc pas une mesure isolant uniquement le coût d’une indirection. Le choix proposé favorise cette sûreté de gestion ; une optimisation par adresse en cache demanderait de qualifier une arène réellement stable et son cycle de vie.</p><p><b>Partager ne supprime pas les notifications.</b> Toutes les variantes parcourent le même index inverse et comptabilisent les alias concernés ; le miroir recopie en plus la valeur. Le banc ne fait pas de véritables envois SSE/MQTT ni de rendu UI. Une mise à jour de la source est O(1) pour le stockage partagé, mais informer f abonnés conserve un coût O(f). Aucun changement matériel ni scénario domotique n’a été exécuté.</p>''')
oldperf=[]
for scale in [1,10,100]:
 group=[next(r for r in V2['results'] if r['dataset']=='somme-detail' and r['scale']==scale and r['layout']==variant) for variant in ['uniform96','uniform64']]
 oldperf.append([f'×{scale}',*[f"{r['numeric_ns_per_op']:.2f}" for r in group],*[f"{r['scan_ns_per_row']:.2f}" for r in group]])
sec('96octets','Conserver96 o est cohérent ; la supériorité universelle n’est pas démontrée.', '''<p>La V3 conserve96 o selon ta préférence : état, identifiants, dates et quartet numérique restent ensemble. Cela peut servir les lectures qui utilisent simultanément les bornes et la valeur. Il faut cependant corriger l’idée «96 o est forcément le plus rapide pour tous les calculs» : la V2 montrait déjà que cela dépend de la charge et de l’accès.</p>'''+table(['Ancien banc V2, mêmes données par format','Lecture nombre+bornes96 ns','Lecture nombre+bornes64 ns','Scan96 ns/ligne','Scan64 ns/ligne'],oldperf)+'''<p>Cette table reprend les résultats V2 archivés, sans mélanger leurs nanosecondes à ceux du nouveau parcours d’alias. Un accès à quatre bornes n’est pas un benchmark complet de moyenne, de durée ou de graphe de calcul. La V3 ne prouve pas que96 accélère tous les moteurs de calcul. Une ligne de96 o n’est pas non plus une ligne de cache matérielle de96 o ; aligner chaque fiche sur64 ferait passer son pas à128 o.</p><p>La décision proposée est donc : <b>96 o pour les vrais états ; pas de nouvel état pour un alias pur</b>. Une valeur calculée reçoit sa propre ligne96 et des dépendances, car son résultat et ses dates lui appartiennent. Si ce calcul est affiché dans plusieurs objets virtuels, ces vues peuvent à leur tour partager son unique ligne calculée.</p>''')
sec('coherence','Accès, disparition d’une source, concurrence et actions', '''<ul><li><b>Lecture seule :</b> le lien expose la capacité de la source, éventuellement restreinte par la vue. Il ne rend jamais inscriptible une source qui ne l’est pas. Les capacités réelles restent à qualifier comme en V2.</li><li><b>Set :</b> résoudre le lien vers la cible physique, conserver demandeur, origine et identité d’alias pour l’audit, puis passer par le hub et sa garde. Une écriture dans la mémoire observée n’est pas une commande d’appareil.</li><li><b>Actions :</b> une action virtuelle peut référencer le contrat réel sans état fictif. Une action composite possède sa propre description, ses droits, sa corrélation et ses reçus ; leur coût n’a pas été inventé dans ce banc d’alias de valeurs.</li><li><b>Source retirée :</b> le handle périmé est refusé ; aucune ancienne adresse ne doit viser un nouvel appareil. Le débordement d’une génération exige de retirer l’emplacement ou changer d’époque, jamais un wrap silencieux.</li><li><b>Catalogue reconstruit :</b> recharger les sources depuis leurs IDs, invalider les caches et publier catalogue+liens de manière cohérente. Les adresses ne sont jamais persistées. La reprise atomique après crash n’est pas implémentée ici.</li><li><b>Concurrence :</b> un seul propriétaire modifie les lignes dans le banc. Des lecteurs concurrents de96 o ont besoin d’un protocole cohérent ; partager une adresse ne rend pas une mise à jour multi-champs atomique.</li><li><b>Textes et composites :</b> la source possède un handle immuable/versionné. Les alias réutilisent ce handle ; un contenu changé sous la même référence doit être interdit ou détecté par une version.</li><li><b>Cycles :</b> les alias du banc ciblent directement des états canoniques. Une implémentation générale doit aplatir les chaînes ou refuser les cycles ; cet algorithme n’est pas qualifié ici.</li></ul>''')
testlog=(HERE/'sorties/tests.txt').read_text();count=re.search(r'(\d+) passed; 0 failed',testlog).group(1)
sec('preuves','Ce qui est prouvé, et ce qui reste à qualifier',f'''<p><b>{count} tests Rust passent ;150 essais Linux donnent50 médianes.</b> Les observations sont comparées à la source avant et après les écritures, avec les mêmes empreintes entre variantes. La décomposition mémoire correspond au compteur d’octets vivants.</p>'''+table(['Critère','État','Périmètre'],[['Formats96/32/128 et comptes mémoire','PASS','Layouts, allocations réelles et sommes de postes.'],['Une source vue par plusieurs alias','PASS','Lecture et mutations, parité miroirs et partage ; notifications parcourues à travail égal.'],['ID, propriétaire et cible distincts','PASS','Index global sans doublons ; parent physique conservé.'],['Handles invalidés, génération et croissance du Vec','PASS','Tests du prototype ; pas de persistance du catalogue.'],['Pointeur sur allocation gelée','PASS fonctionnel','Allocation conservée pendant les emprunts ; pas de validation Miri ni de concurrence.'],['Calculé distinct de sa source','PASS modèle','Propre ligne et résultat indépendant ; pas de qualification du moteur de calcul complet.'],['Durées de vie au rebuild, concurrence, reprise après crash','NON PROUVÉ','Architecture décrite, cycle de vie de production non intégré.'],['Budget total de Moli','NON PROUVÉ','Fixture et buffers de test exclus du compteur ; autres composants absents.']])+f'''<p>Linux ARM64, un CPU alloué, plafond du banc512 Mio pour permettre×100 sans le confondre avec le budget produit32 Mio. Compilation <code>{esc(D['meta']['compile_flags'])}</code>. La conservation des96 o ne garantit pas le budget : les grandes charges et les nombreux alias peuvent dépasser32 Mio sur ce seul prototype, comme le montrent les tableaux.</p><ul><li><a href="../../../tools/alias-banc/main.rs">Code du banc et tests</a> · <a href="../../../tools/alias-banc/README.md">Méthode et reproduction</a>.</li><li><a href="../../../tools/alias-banc/sorties/resultats.json">50 résultats agrégés et empreintes</a> · <a href="../../../tools/alias-banc/sorties/brut.jsonl">150 essais bruts</a> · <a href="../../../tools/alias-banc/sorties/tests.txt">Tests Rust</a>.</li><li><a href="../../../tools/catalogue-banc/charges/manifest.json">Formes anonymisées des deux exports</a> · <a href="catalogue-memoire-v2.html">V2 et comparaison96/64</a>.</li></ul><p>Le code produit de Moli, les instances Home Assistant et les appareils physiques n’ont pas été modifiés. La proposition à retenir est le partage de l’état canonique, avec un lien résolu et contrôlé ; l’adresse brute est une optimisation optionnelle à qualifier.</p>''')
css=re.search(r'<style>(.*?)</style>',(OUT/'catalogue-memoire-v2.html').read_text(),re.S).group(1)
nav=''.join('<a href="#'+id+'">'+esc(title.split(' :')[0])+'</a>' for id,title,_ in sections)
page='<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Moli — Mémoire V3 : valeurs96 et alias partagés</title><style>'+css+'</style></head><body><aside><b>Moli / Alias</b><p>Proposition V3 · valeurs96 o<br>Source unique et liens partagés</p><nav aria-label="Sections">'+nav+'</nav></aside><main><header><span class="badge">PROPOSITION TESTÉE — NON INTÉGRÉE</span><h1>Une valeur.<br>Plusieurs vues.<br>Aucune copie à synchroniser.</h1><p class="lead">Réexaminer les pointeurs en Rust et conserver96 octets pour les véritables états.</p></header>'+''.join(s for _,_,s in sections)+'<footer>Sources privées hors dépôt · aucune commande dans une maison</footer></main></body></html>'
# Typographie des quantités dans la prose ; ne touche pas les noms de variables.
for old_text,new_text in [('conserver96','conserver 96'),('Conserver96','Conserver 96'),('ligne96','ligne 96'),('fiche96','fiche 96'),('alias32','alias 32'),('alias96','alias 96'),('Alias96','Alias 96'),('ligne96','ligne 96'),('lien32','lien 32'),('Liens32','Liens 32'),('miroir128','miroir 128'),('encore96','encore 96'),('copie96','copie 96'),('source96','source 96'),('quartet32','quartet 32'),('bornes96','bornes 96'),('bornes64','bornes 64'),('Scan96','Scan 96'),('Scan64','Scan 64'),('512 Mio','512 Mio'),('banc512','banc 512'),('produit32','produit 32'),('comparaison96','comparaison 96'),('valeurs96','valeurs 96'),(';150','; 150'),('donnent50','donnent 50'),('permettre×','permettre ×'),('tableau96','tableau 96'),('aligner64','aligner 64'),('pas128','pas 128'),('Formats96','Formats 96'),('des96','des 96'),('de96','de 96'),('sur64','sur 64'),('à128','à 128'),('dépasser32','dépasser 32')]:page=page.replace(old_text,new_text)
(OUT/'catalogue-memoire-v3.html').write_text(page)
print(json.dumps(dict(tests=count,source_rows=b['source_rows'],canonical_rows=b['canonical_rows'],aliases=b['aliases'],mirror=m['allocations_requested_bytes'],shared=b['allocations_requested_bytes'],saved=m['allocations_requested_bytes']-b['allocations_requested_bytes']),ensure_ascii=False))
